import os
import torch


class Config:
    # ==========================================
    # 1. File System & Paths
    # ==========================================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"

    # Input Metadata Files (Generated by metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")
    SAMPLE_SUBMISSION = os.path.join(INPUT_ROOT, "sample_submission.csv")

    # Output Directories for the specific idea
    IDEA_NAME = "idea_51"
    # Cache for preprocessed images/features (numpy files)
    CACHE_DIR = os.path.join(WORKING_DIR, IDEA_NAME, "cache")
    # Checkpoints for model weights
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, IDEA_NAME, "checkpoints")
    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # 2. Data Configuration
    # ==========================================
    SEED = 42
    IMAGE_SIZE = 224

    # Tri-Slab Configuration (Fixed Overlapping Orthogonal Tri-Slabs)
    SLAB_COUNT = 3
    SLAB_OVERLAP = 0.15
    VIEWS = ["axial", "coronal"]

    # Tabular Features
    # Note: 'Weeks' is EXCLUDED from input. The model predicts static parameters.
    TABULAR_COLS = ["Age", "Sex", "SmokingStatus", "Percent"]

    # ==========================================
    # 3. Model Hyperparameters (NSL-HN)
    # ==========================================
    BACKBONE_NAME = "efficientnet_b0"
    BACKBONE_PRETRAINED = True
    # EfficientNet-B0 outputs 1280 channels at the final layer
    BACKBONE_OUT_DIM = 1280

    # Shared Latent Topology
    LATENT_DIM = 128

    # Fusion / Attention Block
    ATTN_HEADS = 4
    ATTN_LAYERS = 1
    ATTN_DROPOUT = 0.1

    # Head
    HEAD_HIDDEN_DIM = 128
    DROPOUT_RATE = 0.2

    # ==========================================
    # 4. Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 32
    EPOCHS = 50
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2
    PATIENCE = 8  # Strict early stopping

    # Scheduler
    SCHEDULER_T_MAX = EPOCHS
    SCHEDULER_MIN_LR = 1e-6

    # Hardware
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Debugging / Development
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 100

    # ==========================================
    # 5. Metric & Inference
    # ==========================================
    METRIC_MAX_ERROR = 1000
    METRIC_MIN_CONFIDENCE = 70

    @classmethod
    def setup(cls):
        """Creates necessary output directories."""
        for d in [cls.CACHE_DIR, cls.CHECKPOINT_DIR, cls.SUBMISSION_DIR]:
            os.makedirs(d, exist_ok=True)

    @classmethod
    def set_debug_mode(cls, debug=True, sample_size=100, epochs=2):
        """Adjusts configuration for debugging purposes."""
        cls.DEBUG = debug
        cls.DEBUG_SAMPLE_SIZE = sample_size
        if debug:
            cls.EPOCHS = epochs
            print(
                f"Debug mode enabled: Epochs={cls.EPOCHS}, SampleSize={cls.DEBUG_SAMPLE_SIZE}"
            )


# Initialize directories on import
Config.setup()
